AssistantMessageToolRequest(name='create', tool_call_id='function-call-69b5376c-4f64-446c-8740-c93952ab3c2c', arguments={'file_text': 'const { useState } = React;

const FAQ_DATA = [
    {
        id: 'purr',
        question: 'Why do cats purr?',
        answer: 'While purring is often a sign of contentment, cats also purr when they are stressed, injured, or even giving birth. It is thought to be a self-soothing mechanism and may even help promote bone and tissue healing through low-frequency vibrations.'
    },
    {
        id: 'boxes',
        question: 'Why do cats love boxes?',
        answer: 'Boxes provide a sense of security and safety. In the wild, cats are both predators and prey, so having a confined space where they can hide and observe their surroundings helps reduce stress and provides a "safe zone" from potential threats.'
    },
    {
        id: 'sleep',
        question: 'How much do cats sleep?',
        answer: 'On average, cats sleep between 12 and 16 hours a day. Some cats can even sleep up to 20 hours in a 24-hour period. This behavior is a remnant of their evolutionary history as hunters, where they need to conserve energy for short bursts of high-intensity activity.'
    },
    {
        id: 'whiskers',
        question: 'Why do cats have whiskers?',
        answer: 'Whiskers, or vibrissae, are highly sensitive tactile organs. They help cats navigate in the dark, detect changes in air currents (which can indicate nearby prey), and determine if they can fit through tight spaces. They are essentially a sophisticated sensory system.'
    },
    {
        id: 'knead',
        question: 'Why do cats knead (make biscuits)?',
        answer: 'Kneading is a behavior kittens use to stimulate milk flow from their mothers. Adult cats continue this behavior when they feel happy and comfortable, often as a way to show affection or to create a soft place to sleep. It is a sign of ultimate trust.'
    }
];

function DisclosureItem({ question, answer, id }) {
    const [isExpanded, setIsExpanded] = useState(false);
    const contentId = `details-${id}`;

    return (
        <div className="example">
            <h3>
                <button
                    type="button"
                    aria-expanded={isExpanded}
                    aria-controls={contentId}
                    className="disclosure-button"
                    onClick={() => setIsExpanded(!isExpanded)}
                >
                    <span>{question}</span>
                    <svg
                        className={`icon ${isExpanded ? 'expanded' : ''}`}
                        width="20"
                        height="20"
                        viewBox="0 0 20 20"
                        fill="none"
                        xmlns="http://www.w3.org/2000/svg"
                        aria-hidden="true"
                    >
                        <path
                            d="M5 7.5L10 12.5L15 7.5"
                            stroke="currentColor"
                            strokeWidth="2"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                        />
                    </svg>
                </button>
            </h3>
            {isExpanded && (
                <div id={contentId} className="details">
                    <p>{answer}</p>
                </div>
            )}
        </div>
    );
}

function App() {
    return (
        <main>
            <h1>Cat FAQ</h1>
            <div className="faq-list">
                {FAQ_DATA.map((item) => (
                    <DisclosureItem
                        key={item.id}
                        id={item.id}
                        question={item.question}
                        answer={item.answer}
                    />
                ))}
            </div>
        </main>
    );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
